internal static class Setup {
 internal static JavaScriptSerializer JSON=new JavaScriptSerializer { MaxJsonLength=4000000 };
 internal static Dictionary<string,object> Config=Parse(ReadResource("installer.json"));
 internal static List<Dictionary<string,object>> Models=Rows(Config["models"]);
 internal static string Version=(string)Config["version"];
 internal static string Arg(string key) { var a=Environment.GetCommandLineArgs();var i=Array.IndexOf(a,key);return i>=0&&i+1<a.Length?a[i+1]:null; }
 internal static bool Flag(string key) {return Environment.GetCommandLineArgs().Contains(key);}
 internal static Dictionary<string,object> Parse(string text){return JSON.Deserialize<Dictionary<string,object>>(text);}
 internal static List<Dictionary<string,object>> Rows(object value){return ((IEnumerable)value).Cast<object>().Select(v=>(Dictionary<string,object>)v).ToList();}
 internal static string ReadResource(string name){using(var r=new StreamReader(Assembly.GetExecutingAssembly().GetManifestResourceStream(name)))return r.ReadToEnd();}
 internal static string Hash(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 internal static bool Valid(string path,Dictionary<string,object> info){return File.Exists(path)&&new FileInfo(path).Length==Convert.ToInt64(info["bytes"])&&Hash(path)==(string)info["sha256"];}
 internal static string Canonical(object value){var d=value as Dictionary<string,object>;if(d!=null)return "{"+string.Join(",",d.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>JSON.Serialize(p.Key)+":"+Canonical(p.Value)))+"}";var a=value as IList;if(a!=null)return "["+string.Join(",",a.Cast<object>().Select(Canonical))+"]";return JSON.Serialize(value);}
 internal static string DefaultData(){var selected=ZoteroInstall.Preferred(ZoteroInstall.Profiles());if(selected!=null)return selected.Data;string fallback=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Zotero"),profiles=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"Zotero","Zotero","Profiles");try{if(Directory.Exists(profiles))foreach(var folder in Directory.GetDirectories(profiles).OrderBy(x=>x)){var prefs=Path.Combine(folder,"prefs.js");if(!File.Exists(prefs))continue;var m=Regex.Match(File.ReadAllText(prefs),"user_pref\\(\"extensions\\.zotero\\.dataDir\",\\s*(\"(?:\\\\.|[^\"\\\\])*\")");if(m.Success){var dir=JSON.Deserialize<string>(m.Groups[1].Value);if(File.Exists(Path.Combine(dir,"zotero.sqlite")))return dir;}}}catch(IOException){}return fallback;}
 internal static string ModelRoot(string data){try{var path=Path.Combine(data,"paper-nexus-model-location.json");if(File.Exists(path)&&new FileInfo(path).Length<16384){var record=Parse(File.ReadAllText(path));var root=(string)record["root"];if(Convert.ToInt32(record["schema"])==1&&Path.IsPathRooted(root))return root;}}catch(Exception){}return Path.Combine(data,"paper-nexus-models");}
 internal static void AtomicWrite(string path,string content){var temp=path+".tmp-"+Guid.NewGuid().ToString("N");File.WriteAllText(temp,content,new UTF8Encoding(false));try{if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 [System.Runtime.InteropServices.DllImport("user32.dll")] internal static extern IntPtr SendMessage(IntPtr hWnd,uint message,IntPtr wParam,IntPtr lParam);
 [System.Runtime.InteropServices.DllImport("shell32.dll")] static extern int SHGetKnownFolderPath([System.Runtime.InteropServices.MarshalAs(System.Runtime.InteropServices.UnmanagedType.LPStruct)] Guid id,uint flags,IntPtr token,out IntPtr path);
 internal static string PluginDownloads(){IntPtr path=IntPtr.Zero;try{if(SHGetKnownFolderPath(new Guid("374DE290-123F-4565-9164-39C4925E467B"),0,IntPtr.Zero,out path)==0)return Path.Combine(System.Runtime.InteropServices.Marshal.PtrToStringUni(path),"Paper Nexus");}finally{if(path!=IntPtr.Zero)System.Runtime.InteropServices.Marshal.FreeCoTaskMem(path);}return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads","Paper Nexus");}
 [STAThread] static int Main(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;try{if(Flag("--zotero-probe")){if(Arg("--profiles-ini")==null)throw new Exception("Explicit profiles.ini required");var rows=ZoteroInstall.Profiles(Arg("--profiles-ini"));if(Arg("--stage-profile")!=null){var profile=rows.First(p=>Path.GetFullPath(p.Directory)==Path.GetFullPath(Arg("--stage-profile")));ZoteroInstall.Stage(Arg("--plugin-file"),profile);}var value=JSON.Serialize(new Dictionary<string,object>{{"running",ZoteroInstall.Running()},{"profiles",rows.Select(p=>new Dictionary<string,object>{{"name",p.Name},{"path",p.Directory},{"preferred",p.Preferred},{"installed",ZoteroInstall.Installed(p)},{"data",p.Data}}).ToArray()}});if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),value);else Console.WriteLine(value);return 0;}if(Flag("--quiet")){if(Flag("--plugin-only")){if(Arg("--download-dir")==null)throw new Exception("Download directory required");using(var engine=new Engine()){if(Flag("--cancel-test"))engine.Progress=(phase,p)=>{if(p>0)engine.Cancel();};var file=engine.DownloadPlugin(Arg("--download-dir")).GetAwaiter().GetResult();if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),file);return 0;}}var ids=(Arg("--model")??"minilm").Split(',');var chosen=ids.Select(id=>Models.First(m=>(string)m["id"]==id)).ToList();if(Arg("--data-dir")==null||Arg("--download-dir")==null)throw new Exception("Explicit data and download directories required");using(var engine=new Engine()){if(Flag("--cancel-test"))engine.Progress=(phase,p)=>{if(phase=="model"&&p>0.08)engine.Cancel();};string file=null;foreach(var model in chosen)file=engine.Install(model,Arg("--data-dir"),Arg("--download-dir"),Arg("--model-dir")).GetAwaiter().GetResult();if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),file);return 0;}}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Installer());return 0;}catch(Exception e){if(Arg("--selection-check")!=null)File.WriteAllText(Arg("--selection-check"),e.ToString());if(Arg("--result")!=null)File.WriteAllText(Arg("--result"),e.Message);return 1;}}
}
internal sealed class ZoteroProfile {
 internal string Name,Directory;internal bool Preferred;
 internal string Data {get{var fallback=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Zotero");try{var text=File.ReadAllText(Path.Combine(Directory,"prefs.js"));if(text.Contains("user_pref(\"extensions.zotero.useDataDir\", false)"))return fallback;var m=Regex.Match(text,"user_pref\\(\"extensions\\.zotero\\.dataDir\",\\s*(\"(?:\\\\.|[^\"\\\\])*\")");if(m.Success){var value=Setup.JSON.Deserialize<string>(m.Groups[1].Value);if(Path.IsPathRooted(value))return value;}}catch(IOException){}return fallback;}}
 public override string ToString(){return Name+" — "+Path.GetFileName(Directory);}
}
internal static class ZoteroInstall {
 internal const string ID="cite-lens@local.research";
 internal static List<ZoteroProfile> Profiles(string ini=null){ini=ini??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"Zotero","Zotero","profiles.ini");var rows=new List<ZoteroProfile>();if(!File.Exists(ini))return rows;var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string section="";var fields=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);Action append=()=>{string path,name,relative,pref;if(!section.StartsWith("Profile",StringComparison.OrdinalIgnoreCase)||!fields.TryGetValue("Path",out path)||string.IsNullOrWhiteSpace(path))return;fields.TryGetValue("IsRelative",out relative);if(relative=="0"&&!Path.IsPathRooted(path))return;try{var dir=Path.GetFullPath(relative=="0"?path:Path.Combine(Path.GetDirectoryName(ini),path));if(!Directory.Exists(dir)||!File.Exists(Path.Combine(dir,"prefs.js"))||!seen.Add(dir))return;fields.TryGetValue("Name",out name);fields.TryGetValue("Default",out pref);rows.Add(new ZoteroProfile{Name=name??Path.GetFileName(dir),Directory=dir,Preferred=pref=="1"});}catch(ArgumentException){}catch(NotSupportedException){}};
  try{foreach(var raw in File.ReadAllLines(ini)){var line=raw.Trim().TrimStart('\uFEFF');if(line.StartsWith(";")||line.StartsWith("#"))continue;if(line.StartsWith("[")&&line.EndsWith("]")){append();section=line.Substring(1,line.Length-2);fields.Clear();}else{int equal=line.IndexOf('=');if(equal>0)fields[line.Substring(0,equal).Trim()]=line.Substring(equal+1).Trim();}}append();}catch(IOException){}catch(UnauthorizedAccessException){}return rows;
 }
 internal static ZoteroProfile Preferred(List<ZoteroProfile> rows){if(rows.Count==1)return rows[0];var defaults=rows.Where(p=>p.Preferred).ToList();return defaults.Count==1?defaults[0]:null;}
 internal static string Application(){
  foreach(var p in System.Diagnostics.Process.GetProcessesByName("zotero"))using(p){try{var path=p.MainModule.FileName;if(File.Exists(path))return path;}catch(Exception){}}
  foreach(var hive in new[]{Microsoft.Win32.Registry.CurrentUser,Microsoft.Win32.Registry.LocalMachine}){
   foreach(var key in new[]{@"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\zotero.exe",@"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\App Paths\zotero.exe"})try{using(var entry=hive.OpenSubKey(key)){var value=entry==null?null:entry.GetValue(null) as string;if(value!=null&&File.Exists(value.Trim('"')))return value.Trim('"');}}catch(System.Security.SecurityException){}
   foreach(var prefix in new[]{@"SOFTWARE\Zotero",@"SOFTWARE\WOW6432Node\Zotero"})try{using(var entry=hive.OpenSubKey(prefix)){var version=entry==null?null:entry.GetValue("CurrentVersion") as string;if(version!=null)using(var main=hive.OpenSubKey(prefix+"\\"+version+@"\Main")){var path=main==null?null:main.GetValue("PathToExe") as string;if(path!=null&&File.Exists(path))return path;}}}catch(System.Security.SecurityException){}
  }
  foreach(var basePath in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs")}){var path=Path.Combine(basePath,"Zotero","zotero.exe");if(File.Exists(path))return path;}return null;
 }
 internal static bool Running(){foreach(var name in new[]{"zotero","zotero-bin"}){var processes=System.Diagnostics.Process.GetProcessesByName(name);bool any=processes.Length>0;foreach(var p in processes)p.Dispose();if(any)return true;}return false;}
 internal static bool Installed(ZoteroProfile profile){try{string target=Path.Combine(profile.Directory,"extensions",ID+".xpi"),registry=Path.Combine(profile.Directory,"extensions.json");if(!Setup.Valid(target,(Dictionary<string,object>)Setup.Config["plugin"])||!File.Exists(registry)||new FileInfo(registry).Length>32*1024*1024||File.GetLastWriteTimeUtc(registry)<File.GetLastWriteTimeUtc(target))return false;var record=new JavaScriptSerializer{MaxJsonLength=32*1024*1024}.Deserialize<Dictionary<string,object>>(File.ReadAllText(registry));foreach(var addon in Setup.Rows(record["addons"])){object id,version,active,disabled,blocked;if(addon.TryGetValue("id",out id)&&(string)id==ID&&addon.TryGetValue("version",out version)&&(string)version==Setup.Version&&addon.TryGetValue("active",out active)&&active is bool&&(bool)active&&(!addon.TryGetValue("userDisabled",out disabled)||!(disabled is bool)||!(bool)disabled)&&(!addon.TryGetValue("appDisabled",out blocked)||!(blocked is bool)||!(bool)blocked))return true;}}catch(Exception){}return false;}
 internal static void RefreshStartupCache(ZoteroProfile profile){var cache=Path.Combine(profile.Directory,"addonStartup.json.lz4");if(File.Exists(cache)){File.Copy(cache,Path.Combine(profile.Directory,".paper-nexus-startup.previous"),true);File.Delete(cache);}}
 internal static void Stage(string file,ZoteroProfile profile){var plugin=(Dictionary<string,object>)Setup.Config["plugin"];if(!Directory.Exists(profile.Directory)||!File.Exists(Path.Combine(profile.Directory,"prefs.js"))||!Setup.Valid(file,plugin))throw new Exception("插件或 Zotero 配置校验失败 / Plugin or profile verification failed");if(Installed(profile))return;if(Running())throw new Exception("请正常退出 Zotero 后继续 / Quit Zotero normally, then continue");using(var mutex=new FileStream(Path.Combine(profile.Directory,".paper-nexus-installer.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))using(var profileLock=new FileStream(Path.Combine(profile.Directory,"parent.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
  var folder=Path.Combine(profile.Directory,"extensions");Directory.CreateDirectory(folder);var target=Path.Combine(folder,ID+".xpi");if(Setup.Valid(target,plugin)){RefreshStartupCache(profile);return;}string temp=Path.Combine(folder,".nexus-"+Guid.NewGuid().ToString("N")),backup=Path.Combine(folder,".nexus-previous");bool hadPrevious=File.Exists(target);try{File.Copy(file,temp);File.SetLastWriteTimeUtc(temp,DateTime.UtcNow);if(!Setup.Valid(temp,plugin)||Running())throw new Exception("请退出 Zotero 后重试 / Quit Zotero and retry");if(hadPrevious){if(File.Exists(backup))File.Delete(backup);File.Replace(temp,target,backup);}else File.Move(temp,target);if(!Setup.Valid(target,plugin)){if(hadPrevious&&File.Exists(backup))File.Copy(backup,target,true);throw new Exception("安装校验失败 / Installation verification failed");}}finally{if(File.Exists(temp))File.Delete(temp);}
  RefreshStartupCache(profile);
 }}
}

internal sealed class Engine:IDisposable {
 readonly CancellationTokenSource stop=new CancellationTokenSource();internal Action<string,double> Progress;internal bool Cancelled {get{return stop.IsCancellationRequested;}}internal void Cancel(){stop.Cancel();}public void Dispose(){stop.Dispose();}
 void Check(){stop.Token.ThrowIfCancellationRequested();}
 void Report(string phase,double p){Check();if(Progress!=null)Progress(phase,p);}
 void Verify(string folder,Dictionary<string,object> manifest){foreach(var f in Setup.Rows(manifest["files"])){Check();string name=(string)f["name"];if(Path.GetFileName(name)!=name||!Setup.Valid(Path.Combine(folder,name),f))throw new Exception("模型校验失败 / Model verification failed");}}
 async Task Fetch(Dictionary<string,object> asset,string target,string phase="model"){Check();var uri=new Uri((string)asset["url"]);if(uri.Scheme!="https")throw new Exception("HTTPS required");long expected=Convert.ToInt64(asset["bytes"]);var offline=(phase=="plugin"?Setup.Arg("--plugin-dir"):null)??Setup.Arg("--package-dir");if(offline!=null){File.Copy(Path.Combine(offline,(string)asset["name"]),target);Report(phase,phase=="plugin"?1:0.88);}else{
  using(var handler=new HttpClientHandler {AllowAutoRedirect=false})using(var client=new HttpClient(handler)){client.Timeout=TimeSpan.FromMinutes(15);HttpResponseMessage response=null;try{for(int i=0;i<8;i++){response=await client.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead,stop.Token);if((int)response.StatusCode<300||(int)response.StatusCode>=400)break;var next=response.Headers.Location;if(next==null)throw new Exception("Missing redirect");uri=next.IsAbsoluteUri?next:new Uri(uri,next);response.Dispose();response=null;if(uri.Scheme!="https")throw new Exception("HTTPS required");}if(response==null||response.StatusCode!=HttpStatusCode.OK)throw new Exception("下载暂不可用 / Download unavailable");using(var input=await response.Content.ReadAsStreamAsync())using(var output=File.Create(target)){byte[] buffer=new byte[65536];long total=0;int count;while((count=await input.ReadAsync(buffer,0,buffer.Length,stop.Token))>0){total+=count;if(total>expected)throw new Exception("Unexpected file size");await output.WriteAsync(buffer,0,count,stop.Token);Report(phase,phase=="plugin"?(double)total/expected:0.08+0.80*total/expected);}}}finally{if(response!=null)response.Dispose();}}}
  Check();if(!Setup.Valid(target,asset))throw new Exception("文件校验失败，请重试 / File verification failed");
 }
 internal async Task<string> DownloadPlugin(string downloads){Directory.CreateDirectory(downloads);var plugin=(Dictionary<string,object>)Setup.Config["plugin"];var xpi=Path.Combine(downloads,(string)plugin["name"]);if(!Setup.Valid(xpi,plugin)){Report("plugin",0);var temp=Path.Combine(downloads,".plugin-"+Guid.NewGuid().ToString("N"));try{await Fetch(plugin,temp,"plugin");Check();if(File.Exists(xpi))File.Replace(temp,xpi,null);else File.Move(temp,xpi);}finally{if(File.Exists(temp))File.Delete(temp);}}Check();Report("plugin",1);return xpi;}
 internal async Task<string> Install(Dictionary<string,object> model,string data,string downloads,string modelDirectory=null){if(!File.Exists(Path.Combine(data,"zotero.sqlite")))throw new Exception("请选择包含 zotero.sqlite 的 Zotero 数据目录 / Choose the Zotero data folder containing zotero.sqlite");var root=modelDirectory??Setup.ModelRoot(data);if(root==Path.Combine(data,"paper-nexus-models"))Directory.CreateDirectory(root);if(!Directory.Exists(root))throw new Exception("模型目录不可用，请重新选择 / Model folder unavailable; choose an existing folder");using(var mutex=new FileStream(Path.Combine(root,".installer.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var work=Path.Combine(root,".setup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);try{
  var manifest=(Dictionary<string,object>)model["manifest"];var parent=Path.Combine(root,(string)model["id"]);var target=Path.Combine(parent,(string)manifest["version"]);var xpi=await DownloadPlugin(downloads);
  bool usable=false;if(Directory.Exists(target)){Report("verify",0.08);try{Verify(target,manifest);usable=true;}catch(IOException){}catch(Exception){Check();}}
  if(!usable){var asset=(Dictionary<string,object>)model["package"];var archive=Path.Combine(downloads,(string)asset["name"]);if(!Setup.Valid(archive,asset)){var partial=Path.Combine(downloads,".model-"+Guid.NewGuid().ToString("N"));try{await Fetch(asset,partial);if(File.Exists(archive))File.Replace(partial,archive,null);else File.Move(partial,archive);}finally{if(File.Exists(partial))File.Delete(partial);}}Report("verify",0.89);var extracted=Path.Combine(work,"verified");Directory.CreateDirectory(extracted);var files=Setup.Rows(manifest["files"]);var expected=new HashSet<string>(files.Select(f=>(string)f["name"]),StringComparer.Ordinal){"manifest.json"};var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   using(var zip=ZipFile.OpenRead(archive)){foreach(var entry in zip.Entries){Check();if(!expected.Contains(entry.FullName)||!seen.Add(entry.FullName)||Path.GetFileName(entry.FullName)!=entry.FullName)throw new Exception("Unexpected model archive entry");long limit=entry.FullName=="manifest.json"?4000000:Convert.ToInt64(files.First(f=>(string)f["name"]==entry.FullName)["bytes"]);if(entry.Length>limit)throw new Exception("Unexpected model file size");entry.ExtractToFile(Path.Combine(extracted,entry.FullName));}if(seen.Count!=expected.Count)throw new Exception("Incomplete model package");}
   var actualIdentity=Setup.Parse(File.ReadAllText(Path.Combine(extracted,"manifest.json")));var expectedIdentity=new Dictionary<string,object>(manifest);actualIdentity.Remove("name");expectedIdentity.Remove("name");if(Setup.Canonical(actualIdentity)!=Setup.Canonical(expectedIdentity))throw new Exception("Model manifest mismatch");Verify(extracted,manifest);Report("install",0.97);Directory.CreateDirectory(parent);var backup=Path.Combine(work,"previous");if(Directory.Exists(target))Directory.Move(target,backup);try{Directory.Move(extracted,target);}catch{if(Directory.Exists(backup))Directory.Move(backup,target);throw;}}
  string pointer=Path.Combine(parent,"active.json"),staged=Path.Combine(parent,".active-"+Guid.NewGuid().ToString("N"));File.WriteAllText(staged,Setup.JSON.Serialize(manifest),new UTF8Encoding(false));try{if(File.Exists(pointer))File.Replace(staged,pointer,null);else File.Move(staged,pointer);}finally{if(File.Exists(staged))File.Delete(staged);}Setup.AtomicWrite(Path.Combine(data,"paper-nexus-model-location.json"),Setup.JSON.Serialize(new Dictionary<string,object>{{"schema",1},{"root",Path.GetFullPath(root)}}));if(Progress!=null)Progress("done",1);return xpi;
 }finally{if(Directory.Exists(work))Directory.Delete(work,true);}}}
}
internal static class Visual {
 internal static Color ColorFor(string name){return ColorTranslator.FromHtml((string)((Dictionary<string,object>)Setup.Config["appearance"])[name]);}
 internal static readonly Color Ink=ColorFor("ink"),Muted=ColorFor("muted"),Green=ColorFor("success"),Paper=ColorFor("paper"),Accent=ColorFor("accent"),Card=ColorFor("card"),Button=ColorFor("button");
 static readonly System.Drawing.Text.PrivateFontCollection Fonts=new System.Drawing.Text.PrivateFontCollection();
 [System.Runtime.InteropServices.DllImport("gdi32.dll")]static extern IntPtr AddFontMemResourceEx(IntPtr p,uint size,IntPtr reserved,ref uint count);
