 internal static Font Font(float size,FontStyle weight=FontStyle.Regular){return new Font(Face((weight&FontStyle.Bold)!=0),size*.75f,FontStyle.Regular,GraphicsUnit.Point);}
 internal static Font Resolve(Font font){return new Font(Face(font.FontFamily.Name.Contains("SemiBold")),font.SizeInPoints,FontStyle.Regular,GraphicsUnit.Point);}
 internal static void DrawText(Graphics g,string text,Font font,Rectangle bounds,Color color,bool center=false,bool path=false){g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;using(var face=Resolve(font))using(var brush=new SolidBrush(color))using(var format=new StringFormat {Alignment=center?StringAlignment.Center:StringAlignment.Near,LineAlignment=StringAlignment.Center,Trimming=path?StringTrimming.EllipsisPath:StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap})g.DrawString(text,face,brush,bounds,format);}
 internal static System.Drawing.Drawing2D.GraphicsPath Round(RectangleF r,float radius){var p=new System.Drawing.Drawing2D.GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
