 bool ResolveProfile(){if(profileResolved)return true;var rows=ZoteroInstall.Profiles();zoteroProfile=ZoteroInstall.Preferred(rows);if(zoteroProfile==null&&rows.Count>0){using(var dialog=new Form{Text=T("选择 Zotero 配置","Choose a Zotero profile"),ClientSize=new Size(460,138),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,StartPosition=FormStartPosition.CenterParent,BackColor=Visual.Paper,Font=Visual.Font(13)}){
