 void RefreshPlugin(){if(xpi==null)return;var labels=new Dictionary<string,string>{{"downloaded",T("已下载","Downloaded")},{"waiting",T("待继续","Paused")},{"pending",T("待启用","Enable in Zotero")},{"installed",T("已安装","Installed")},{"manual",T("已下载","Downloaded")}};pluginLabel.Text="Paper Nexus · v"+Setup.Version+" · "+labels[pluginState];pluginButton.Text=pluginState=="pending"||pluginState=="installed"?T("打开 Zotero","Open Zotero"):pluginState=="manual"?T("打开文件","Show XPI"):T("继续安装","Continue setup");if(complete)action.Text=pluginState=="manual"?T("打开插件文件夹","Show plugin file"):pluginState=="pending"||pluginState=="installed"?T("打开 Zotero","Open Zotero"):T("继续安装","Continue setup");if(pluginState=="pending")status.Text=T("待启用：在 Zotero「工具 → 插件」中启用 Paper Nexus。","Enable Paper Nexus in Zotero → Tools → Plugins.");else if(pluginState=="installed")status.Text=T("插件已安装并启用。","Plugin installed and enabled.");else if(pluginState=="manual")status.Text=T("未识别到 Zotero 或配置。请在 Zotero 中从文件安装已下载的 XPI。","Zotero or its profile was not found. Install the downloaded XPI from file in Zotero.");}
 async Task InstallPlugin(){if(xpi==null)return;if(zoteroProfile==null||ZoteroInstall.Application()==null){pluginState="manual";RefreshPlugin();return;}if(await Task.Run(()=>ZoteroInstall.Installed(zoteroProfile))){pluginState="installed";RefreshPlugin();return;}if(ZoteroInstall.Running()){pluginState="waiting";RefreshPlugin();if(MessageBox.Show(this,T("请正常退出 Zotero，保存正在阅读或编辑的内容，再点击确定继续。","Quit Zotero normally after saving your work, then click OK to continue."),T("请先退出 Zotero","Quit Zotero to continue"),MessageBoxButtons.OKCancel,MessageBoxIcon.Information)==DialogResult.OK){if(!ZoteroInstall.Running())await InstallPlugin();}return;}Busy(true);cancel.Visible=false;status.Text=T("正在安装插件…","Installing plugin…");try{await Task.Run(()=>ZoteroInstall.Stage(xpi,zoteroProfile));Busy(false);pluginState="pending";RefreshPlugin();PollPlugin();}catch(Exception error){Busy(false);pluginState="downloaded";RefreshPlugin();status.Text=error.Message;}}
 async void PollPlugin(){if(pluginState!="pending"||polling||zoteroProfile==null)return;polling=true;try{while(!IsDisposed&&pluginState=="pending"){await Task.Delay(2000);if(IsDisposed)break;bool installed=await Task.Run(()=>ZoteroInstall.Installed(zoteroProfile));if(installed){pluginState="installed";if(!busy)RefreshPlugin();break;}}}finally{polling=false;}}
